        "copy": "Download Obsidian now",
        "sub": "obsidian.md — free. Open folder as vault. Point at Cowork. Change one line in about-me. Watch it land."
      },
      "new_visual_element": "[HANDOFF] your-turn card",
      "build": {
        "status": "VIDEO",
        "src": "media/B08.mp4",
        "filled_by": "media",
        "at": "2026-08-10T03:51:22"
      },
      "actual_duration_s": 12.86,
      "audio_file": "mp3/beat-B08.mp3"
    },
    {
      "beat_id": "B09",
      "t_start": 79.0,
      "estimated_duration_s": 11.0,
      "narration_text": "Stop prompting. Let the files do the prompting. Your Second Brain, for free. This is Liam, in for Bear.",
